import fs from 'node:fs';import assert from 'node:assert/strict';import {dshRecordItems} from '../runtime/resources/app/lib/dsh-events.mjs';
let checks=0;const check=(n,v)=>{assert.ok(v,n);checks++;console.log('PASS',n)};const base='http://127.0.0.1:7814';const projects=await(await fetch(base+'/api/projects')).json();const dsh=projects.agents.find(a=>a.id==='dsh');const project=dsh.projects.find(p=>p.path.toLowerCase()==='d:\\dsh');assert.ok(project);const sessions=project.sessions;const target=sessions.find(s=>s.id==='dsh:session-<session-id>');check('actual resumed DSH title reads latest native title',target?.title==='修复dsh插件并优化性能');check('actual resumed DSH uses recent update ordering',Date.now()-target.ts<24*3600000&&sessions.findIndex(s=>s.id===target.id)<5);
const history=await(await fetch(base+'/api/session?id='+encodeURIComponent(target.id))).json();check('actual DSH history includes reasoning',history.messages.some(m=>m.role==='reasoning'));check('actual DSH history includes tool results',history.messages.some(m=>m.role==='tool'&&m.text==='工具结果'&&m.meta));check('actual DSH history includes nested tool calls',history.messages.some(m=>m.role==='tool'&&m.text!=='工具结果'));
const state=await(await fetch(base+'/api/state')).json();const agent=state.agents.find(a=>a.id==='dsh');check('live DSH monitor emits actual events rather than directory placeholders',agent.feed.some(f=>['tool','ask','done','info'].includes(f.kind))&&!agent.feed.some(f=>f.kind==='session'));check('live DSH event times valid',agent.feed.every(f=>f.ts>1e12));
const items=dshRecordItems({type:'assistant/message',seq:1,time:1234567890123,data:{message:{id:'x',content:[{type:'reasoning',text:'reason'},{type:'text',text:'reply'}]}}});check('one native assistant event preserves thought and answer',items.length===2&&items.some(i=>i.role==='reasoning')&&items.some(i=>i.role==='assistant'));
const evidence={passed:true,checks,source:'read-only actual native DSH session files and local monitor API; no native process restart or model call',session:{id:target.id,title:target.title,updatedAt:target.ts,messages:history.messages.length},monitor:{phase:agent.activity.phase,busy:agent.busy,source:agent.activity.source,feed:agent.feed.slice(-6).map(f=>({kind:f.kind,role:f.role,ts:f.ts,text:f.text.slice(0,80)}))}};fs.writeFileSync('tools/dsh-live-results-20261101.json',JSON.stringify(evidence,null,2));console.log(JSON.stringify({checks,messages:history.messages.length,feed:agent.feed.length}));
